            println!("{}", "-".repeat(74));

            for f in &result.functions {
                println!(
                    "{:<40} {:>10} {:#12x} {:>8}",
                    truncate(&f.name, 40),
                    f.size,
                    f.address,
                    f.references
                );
            }
        }
    }

    Ok(())
}

fn truncate(s: &str, max_len: usize) -> String {
    if s.len() <= max_len {
        s.to_string()
    } else {
        format!("{}...", &s[..max_len - 3])
    }
}
