/// Get the size of the .text section
fn get_text_section_size(elf: &Elf) -> u64 {
    elf.section_headers
        .iter()
        .find(|sh| elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".text")
        .map(|sh| sh.sh_size)
        .unwrap_or(0)
