/// Count call references to functions using disassembly
fn count_references(
    args: &Args,
    elf: &Elf,
    binary_data: &[u8],
    functions: &mut HashMap<u64, FunctionInfo>,
) -> Result<()> {
    // Find executable sections
    for shdr in &elf.section_headers {
        // Check if section is executable (SHF_EXECINSTR = 0x4)
        if shdr.sh_flags & 0x4 == 0 {
            continue;
        }

        let section_name = elf.shdr_strtab.get_at(shdr.sh_name).unwrap_or("");

        // Skip PLT itself to avoid double-counting
        if section_name == ".plt" || section_name == ".plt.got" {
            continue;
        }

        let start = shdr.sh_offset as usize;
        let end = start + shdr.sh_size as usize;

        if end > binary_data.len() {
            continue;
        }

        let section_data = &binary_data[start..end];
        let section_addr = shdr.sh_addr;

        // Decode with iced-x86
        let mut decoder = Decoder::with_ip(64, section_data, section_addr, DecoderOptions::NONE);
        let mut insn = Instruction::default();

        while decoder.can_decode() {
            decoder.decode_out(&mut insn);

            // Look for call instructions (not indirect calls)
            if insn.flow_control() == FlowControl::Call {
                if let Some(target) = extract_call_target(&insn) {
                    if let Some(func) = functions.get_mut(&target) {
                        func.references += 1;
                        if args.verbose {
                            eprintln!(
                                "  0x{:x}: call -> {} (0x{:x})",
                                insn.ip(),
                                func.name,
                                target
                            );
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

/// Extract the target address from a call instruction
fn extract_call_target(insn: &Instruction) -> Option<u64> {
    // Check if it's a near branch (direct call)
    if insn.op0_kind() == OpKind::NearBranch64 {
        Some(insn.near_branch_target())
    } else if insn.op0_kind() == OpKind::NearBranch32 {
        Some(insn.near_branch_target())
    } else if insn.op0_kind() == OpKind::NearBranch16 {
        Some(insn.near_branch_target())
    } else {
        // Indirect call (register or memory) - can't resolve statically
        None
    }
}

