   138→/// Run compare mode: compare function sizes between two binaries
   139→fn run_compare(funcs_file: &PathBuf, binary1: &PathBuf, binary2: &PathBuf) -> Result<()> {
   140→    // Read function names from file
   141→    let file = fs::File::open(funcs_file)
   142→        .with_context(|| format!("Failed to open functions file: {:?}", funcs_file))?;
   143→    let reader = BufReader::new(file);
   144→    let func_names: Vec<String> = reader
   145→        .lines()
   146→        .filter_map(|line| line.ok())
   147→        .map(|s| s.trim().to_string())
   148→        .filter(|s| !s.is_empty() && !s.starts_with('#'))
   149→        .collect();
   150→
   151→    // Get function sizes from both binaries
   152→    let sizes1 = get_function_sizes(binary1)?;
   153→    let sizes2 = get_function_sizes(binary2)?;
   154→
   155→    // Get binary names for header
   156→    let name1 = binary1.file_name().unwrap_or_default().to_string_lossy();
   157→    let name2 = binary2.file_name().unwrap_or_default().to_string_lossy();
   158→
   159→    // Print comparison table
   160→    println!("{:<40} {:>12} {:>12} {:>10}", "FUNCTION", name1, name2, "RATIO");
   161→    println!("{}", "-".repeat(76));
   162→
   163→    let mut total1: u64 = 0;
   164→    let mut total2: u64 = 0;
   165→    let mut compared = 0;
   166→
   167→    for func in &func_names {
   168→        let size1 = sizes1.get(func).copied();
   169→        let size2 = sizes2.get(func).copied();
   170→
   171→        let s1_str = size1.map(|s| s.to_string()).unwrap_or_else(|| "-".to_string());
   172→        let s2_str = size2.map(|s| s.to_string()).unwrap_or_else(|| "-".to_string());
   173→
   174→        let ratio_str = match (size1, size2) {
   175→            (Some(s1), Some(s2)) if s1 > 0 => {
   176→                total1 += s1;
   177→                total2 += s2;
   178→                compared += 1;
   179→                format!("{:.1}x", s2 as f64 / s1 as f64)
   180→            }
   181→            _ => "-".to_string(),
   182→        };
   183→
   184→        println!("{:<40} {:>12} {:>12} {:>10}", func, s1_str, s2_str, ratio_str);
   185→    }
   186→
   187→    println!("{}", "-".repeat(76));
   188→    println!("{:<40} {:>12} {:>12} {:>10}",
   189→        format!("TOTAL ({} functions)", compared),
   190→        total1,
   191→        total2,
   192→        if total1 > 0 { format!("{:.1}x", total2 as f64 / total1 as f64) } else { "-".to_string() }
   193→    );
   194→
   195→    Ok(())
   196→}
   197→
   198→/// Extract function name -> size map from a binary
   199→fn get_function_sizes(binary: &PathBuf) -> Result<HashMap<String, u64>> {
   200→    let binary_data = fs::read(binary)
   201→        .with_context(|| format!("Failed to read binary: {:?}", binary))?;
   202→
   203→    let elf = Elf::parse(&binary_data)
   204→        .with_context(|| format!("Failed to parse ELF: {:?}", binary))?;
   205→
   206→    let mut sizes = HashMap::new();
   207→
   208→    // Check .symtab
   209→    for sym in &elf.syms {
   210→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   211→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   212→            sizes.insert(name.to_string(), sym.st_size);
   213→        }
   214→    }
   215→
   216→    // Check .dynsym
   217→    for sym in &elf.dynsyms {
   218→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   219→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   220→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   221→        }
   222→    }
   223→
   224→    Ok(sizes)
   225→}
   226→
   227→/// Get the size of the .text section
   228→fn get_text_section_size(elf: &Elf) -> u64 {
   229→    elf.section_headers
   230→        .iter()
   231→        .find(|sh| elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".text")
   232→        .map(|sh| sh.sh_size)
   233→        .unwrap_or(0)
   234→}
   235→
   236→/// Analyze a statically linked binary
   237→fn analyze_static(args: &Args, binary_path: &PathBuf, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   238→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   239→
   240→    // Collect function symbols from .symtab
   241→    for sym in &elf.syms {
   242→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   243→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   244→
   245→            // Skip if filtering and doesn't match
   246→            if let Some(ref filter) = args.filter {
   247→                if !name.contains(filter) {
   248→                    continue;
   249→                }
   250→            }
   251→
   252→            functions.insert(sym.st_value, FunctionInfo {
   253→                name: name.to_string(),
   254→                size: sym.st_size,
   255→                address: sym.st_value,
   256→                references: 0,
   257→                source: Some("local".to_string()),
   258→            });
   259→        }
   260→    }
   261→
   262→    // Also check .dynsym (release builds may strip .symtab but keep .dynsym)
   263→    for sym in &elf.dynsyms {
   264→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   265→            // Skip if we already have this address from symtab
   266→            if functions.contains_key(&sym.st_value) {
   267→                continue;
   268→            }
   269→
   270→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   271→
   272→            // Skip if filtering and doesn't match
   273→            if let Some(ref filter) = args.filter {
   274→                if !name.contains(filter) {
   275→                    continue;
   276→                }
   277→            }
   278→
   279→            functions.insert(sym.st_value, FunctionInfo {
   280→                name: name.to_string(),
   281→                size: sym.st_size,
   282→                address: sym.st_value,
   283→                references: 0,
   284→                source: Some("local".to_string()),
   285→            });
   286→        }
   287→    }
   288→
   289→    // Count references by disassembling
   290→    count_references(args, elf, binary_data, &mut functions)?;
   291→
   292→    // Convert to sorted vec
   293→    let mut func_vec: Vec<_> = functions.into_values().collect();
   294→    filter_and_sort(&args, &mut func_vec);
   295→
   296→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   297→    let text_section_size = get_text_section_size(elf);
   298→
   299→    Ok(AnalysisResult {
   300→        binary_path: binary_path.display().to_string(),
   301→        is_dynamic: false,
   302→        total_functions: func_vec.len(),
   303→        total_code_size,
   304→        text_section_size,
   305→        functions: func_vec,
   306→    })
   307→}
   308→
   309→/// Analyze a dynamically linked binary
   310→fn analyze_dynamic(args: &Args, binary_path: &PathBuf, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   311→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   312→
   313→    // For dynamic binaries, we care about:
   314→    // 1. Imported symbols (from .dynsym with UND section)
   315→    // 2. PLT entries that reference them
   316→
   317→    // Build a map of PLT entries to function names
   318→    let plt_map = build_plt_map(elf)?;
   319→
   320→    // Get sizes from libc if path provided
   321→    let libc_sizes = if let Some(ref libc_path) = args.libc_path {
   322→        load_libc_sizes(libc_path)?
   323→    } else {
   324→        HashMap::new()
   325→    };
   326→
   327→    // Collect imported libc functions
   328→    for sym in &elf.dynsyms {
   329→        if sym.st_type() == goblin::elf::sym::STT_FUNC {
   330→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   331→
   332→            if sym.st_shndx == goblin::elf::section_header::SHN_UNDEF as usize {
   333→                // Skip if filtering and doesn't match
   334→                if let Some(ref filter) = args.filter {
   335→                    if !name.contains(filter) {
   336→                        continue;
   337→                    }
   338→                }
   339→
   340→                // Find PLT address for this symbol
   341→                let plt_addr = plt_map.get(name).copied();
   342→
   343→                let size = libc_sizes.get(name).copied().unwrap_or(0);
   344→
   345→                if let Some(addr) = plt_addr {
   346→                    functions.insert(addr, FunctionInfo {
   347→                        name: name.to_string(),
   348→                        size,
   349→                        address: addr,
   350→                        references: 0,
   351→                        source: Some("glibc".to_string()),
   352→                    });
   353→                }
   354→            }
   355→        }
   356→    }
   357→
   358→    // Count references to PLT stubs
   359→    count_references(args, elf, binary_data, &mut functions)?;
   360→
   361→    let mut func_vec: Vec<_> = functions.into_values().collect();
   362→    filter_and_sort(&args, &mut func_vec);
   363→
   364→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   365→    let text_section_size = get_text_section_size(elf);
   366→
   367→    Ok(AnalysisResult {
   368→        binary_path: binary_path.display().to_string(),
   369→        is_dynamic: true,
   370→        total_functions: func_vec.len(),
   371→        total_code_size,
   372→        text_section_size,
   373→        functions: func_vec,
   374→    })
   375→}
   376→
   377→/// Build a map of function names to their PLT addresses
   378→fn build_plt_map(elf: &Elf) -> Result<HashMap<String, u64>> {
   379→    let mut plt_map = HashMap::new();
   380→
   381→    // Find .rela.plt section for PLT relocations
   382→    for reloc in &elf.pltrelocs {
   383→        let sym_idx = reloc.r_sym;
   384→        if let Some(sym) = elf.dynsyms.get(sym_idx) {
   385→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   386→
   387→            // PLT entry address: typically the relocation target + PLT base
   388→            // This is simplified; real PLT layout varies
   389→            if let Some(plt_shdr) = elf.section_headers.iter()
   390→                .find(|sh| {
   391→                    elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".plt"
   392→                })
   393→            {
   394→                // Each PLT entry is typically 16 bytes on x86_64
   395→                // First entry is resolver, real entries start at +16
   396→                let plt_entry_addr = plt_shdr.sh_addr + 16 + (plt_map.len() as u64 * 16);
   397→                plt_map.insert(name.to_string(), plt_entry_addr);
   398→            }
   399→        }
   400→    }
   401→
   402→    Ok(plt_map)
   403→}
   404→
   405→/// Load function sizes from a glibc shared library
   406→fn load_libc_sizes(libc_path: &PathBuf) -> Result<HashMap<String, u64>> {
   407→    let data = fs::read(libc_path)
   408→        .with_context(|| format!("Failed to read libc: {:?}", libc_path))?;
   409→
   410→    let elf = Elf::parse(&data)?;
   411→    let mut sizes = HashMap::new();
   412→
   413→    for sym in &elf.dynsyms {
   414→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   415→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   416→            sizes.insert(name.to_string(), sym.st_size);
   417→        }
   418→    }
   419→
   420→    // Also check regular symtab if available
   421→    for sym in &elf.syms {
   422→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   423→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   424→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   425→        }
   426→    }
   427→
   428→    Ok(sizes)
   429→}
   430→
   431→/// Count call references to functions using disassembly
   432→fn count_references(
   433→    args: &Args,
   434→    elf: &Elf,
   435→    binary_data: &[u8],
   436→    functions: &mut HashMap<u64, FunctionInfo>,
   437→) -> Result<()> {
   438→    let cs = Capstone::new()
   439→        .x86()
   440→        .mode(arch::x86::ArchMode::Mode64)
   441→        .syntax(arch::x86::ArchSyntax::Att)
   442→        .detail(true)
   443→        .build()
   444→        .map_err(|e| anyhow::anyhow!("Failed to create Capstone: {}", e))?;
   445→
   446→    // Find executable sections
   447→    for shdr in &elf.section_headers {
   448→        // Check if section is executable (SHF_EXECINSTR = 0x4)
   449→        if shdr.sh_flags & 0x4 == 0 {
   450→            continue;
   451→        }
   452→
   453→        let section_name = elf.shdr_strtab.get_at(shdr.sh_name).unwrap_or("");
   454→
   455→        // Skip PLT itself to avoid double-counting
   456→        if section_name == ".plt" || section_name == ".plt.got" {
   457→            continue;
   458→        }
   459→
   460→        let start = shdr.sh_offset as usize;
   461→        let end = start + shdr.sh_size as usize;
   462→
   463→        if end > binary_data.len() {
   464→            continue;
   465→        }
   466→
   467→        let section_data = &binary_data[start..end];
