   143→    println!("{}", "-".repeat(76));
   144→
   145→    let mut total1: u64 = 0;
   146→    let mut total2: u64 = 0;
   147→    let mut compared = 0;
   148→
   149→    for func in &func_names {
   150→        let size1 = sizes1.get(func).copied();
   151→        let size2 = sizes2.get(func).copied();
   152→
   153→        let s1_str = size1.map(|s| s.to_string()).unwrap_or_else(|| "-".to_string());
   154→        let s2_str = size2.map(|s| s.to_string()).unwrap_or_else(|| "-".to_string());
   155→
   156→        let ratio_str = match (size1, size2) {
   157→            (Some(s1), Some(s2)) if s1 > 0 => {
   158→                total1 += s1;
   159→                total2 += s2;
   160→                compared += 1;
   161→                format!("{:.1}x", s2 as f64 / s1 as f64)
   162→            }
   163→            _ => "-".to_string(),
   164→        };
   165→
   166→        println!("{:<40} {:>12} {:>12} {:>10}", func, s1_str, s2_str, ratio_str);
   167→    }
   168→
   169→    println!("{}", "-".repeat(76));
   170→    println!("{:<40} {:>12} {:>12} {:>10}",
   171→        format!("TOTAL ({} functions)", compared),
   172→        total1,
   173→        total2,
   174→        if total1 > 0 { format!("{:.1}x", total2 as f64 / total1 as f64) } else { "-".to_string() }
   175→    );
   176→
   177→    Ok(())
   178→}
   179→
   180→/// Extract function name -> size map from a binary
   181→fn get_function_sizes(binary: &PathBuf) -> Result<HashMap<String, u64>> {
   182→    let binary_data = fs::read(binary)
   183→        .with_context(|| format!("Failed to read binary: {:?}", binary))?;
   184→
   185→    let elf = Elf::parse(&binary_data)
   186→        .with_context(|| format!("Failed to parse ELF: {:?}", binary))?;
   187→
   188→    let mut sizes = HashMap::new();
   189→
   190→    // Check .symtab
   191→    for sym in &elf.syms {
   192→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   193→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   194→            sizes.insert(name.to_string(), sym.st_size);
   195→        }
   196→    }
   197→
   198→    // Check .dynsym
   199→    for sym in &elf.dynsyms {
   200→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   201→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   202→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   203→        }
   204→    }
   205→
   206→    Ok(sizes)
   207→}
   208→
   209→/// Get the size of the .text section
   210→fn get_text_section_size(elf: &Elf) -> u64 {
   211→    elf.section_headers
   212→        .iter()
   213→        .find(|sh| elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".text")
   214→        .map(|sh| sh.sh_size)
   215→        .unwrap_or(0)
   216→}
   217→
   218→/// Analyze a statically linked binary
   219→fn analyze_static(args: &Args, binary_path: &PathBuf, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   220→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   221→
   222→    // Collect function symbols from .symtab
   223→    for sym in &elf.syms {
   224→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   225→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   226→
   227→            // Skip if filtering and doesn't match
   228→            if let Some(ref filter) = args.filter {
   229→                if !name.contains(filter) {
   230→                    continue;
   231→                }
   232→            }
   233→
   234→            functions.insert(sym.st_value, FunctionInfo {
   235→                name: name.to_string(),
   236→                size: sym.st_size,
   237→                address: sym.st_value,
   238→                references: 0,
   239→                source: Some("local".to_string()),
   240→            });
   241→        }
   242→    }
   243→
   244→    // Also check .dynsym (release builds may strip .symtab but keep .dynsym)
   245→    for sym in &elf.dynsyms {
   246→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   247→            // Skip if we already have this address from symtab
   248→            if functions.contains_key(&sym.st_value) {
   249→                continue;
   250→            }
   251→
   252→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   253→
   254→            // Skip if filtering and doesn't match
   255→            if let Some(ref filter) = args.filter {
   256→                if !name.contains(filter) {
   257→                    continue;
   258→                }
   259→            }
   260→
   261→            functions.insert(sym.st_value, FunctionInfo {
   262→                name: name.to_string(),
   263→                size: sym.st_size,
   264→                address: sym.st_value,
   265→                references: 0,
   266→                source: Some("local".to_string()),
   267→            });
   268→        }
   269→    }
   270→
   271→    // Count references by disassembling
   272→    count_references(args, elf, binary_data, &mut functions)?;
   273→
   274→    // Convert to sorted vec
   275→    let mut func_vec: Vec<_> = functions.into_values().collect();
   276→    filter_and_sort(&args, &mut func_vec);
   277→
   278→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   279→    let text_section_size = get_text_section_size(elf);
   280→
   281→    Ok(AnalysisResult {
   282→        binary_path: binary_path.display().to_string(),
   283→        is_dynamic: false,
   284→        total_functions: func_vec.len(),
   285→        total_code_size,
   286→        text_section_size,
   287→        functions: func_vec,
   288→    })
   289→}
   290→
   291→/// Analyze a dynamically linked binary
   292→fn analyze_dynamic(args: &Args, binary_path: &PathBuf, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   293→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   294→
   295→    // For dynamic binaries, we care about:
   296→    // 1. Imported symbols (from .dynsym with UND section)
   297→    // 2. PLT entries that reference them
   298→
   299→    // Build a map of PLT entries to function names
   300→    let plt_map = build_plt_map(elf)?;
   301→
   302→    // Get sizes from libc if path provided
   303→    let libc_sizes = if let Some(ref libc_path) = args.libc_path {
   304→        load_libc_sizes(libc_path)?
   305→    } else {
   306→        HashMap::new()
   307→    };
   308→
   309→    // Collect imported libc functions
   310→    for sym in &elf.dynsyms {
   311→        if sym.st_type() == goblin::elf::sym::STT_FUNC {
   312→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   313→
   314→            if sym.st_shndx == goblin::elf::section_header::SHN_UNDEF as usize {
   315→                // Skip if filtering and doesn't match
   316→                if let Some(ref filter) = args.filter {
   317→                    if !name.contains(filter) {
   318→                        continue;
   319→                    }
   320→                }
   321→
   322→                // Find PLT address for this symbol
   323→                let plt_addr = plt_map.get(name).copied();
   324→
   325→                let size = libc_sizes.get(name).copied().unwrap_or(0);
   326→
   327→                if let Some(addr) = plt_addr {
   328→                    functions.insert(addr, FunctionInfo {
   329→                        name: name.to_string(),
   330→                        size,
   331→                        address: addr,
   332→                        references: 0,
   333→                        source: Some("glibc".to_string()),
   334→                    });
   335→                }
   336→            }
   337→        }
   338→    }
   339→
   340→    // Count references to PLT stubs
   341→    count_references(args, elf, binary_data, &mut functions)?;
   342→
   343→    let mut func_vec: Vec<_> = functions.into_values().collect();
   344→    filter_and_sort(&args, &mut func_vec);
   345→
   346→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   347→    let text_section_size = get_text_section_size(elf);
   348→
   349→    Ok(AnalysisResult {
   350→        binary_path: binary_path.display().to_string(),
   351→        is_dynamic: true,
   352→        total_functions: func_vec.len(),
   353→        total_code_size,
   354→        text_section_size,
   355→        functions: func_vec,
   356→    })
   357→}
   358→
   359→/// Build a map of function names to their PLT addresses
   360→fn build_plt_map(elf: &Elf) -> Result<HashMap<String, u64>> {
   361→    let mut plt_map = HashMap::new();
   362→
   363→    // Find .rela.plt section for PLT relocations
   364→    for reloc in &elf.pltrelocs {
   365→        let sym_idx = reloc.r_sym;
   366→        if let Some(sym) = elf.dynsyms.get(sym_idx) {
   367→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   368→
   369→            // PLT entry address: typically the relocation target + PLT base
   370→            // This is simplified; real PLT layout varies
   371→            if let Some(plt_shdr) = elf.section_headers.iter()
   372→                .find(|sh| {
   373→                    elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".plt"
   374→                })
   375→            {
   376→                // Each PLT entry is typically 16 bytes on x86_64
   377→                // First entry is resolver, real entries start at +16
   378→                let plt_entry_addr = plt_shdr.sh_addr + 16 + (plt_map.len() as u64 * 16);
   379→                plt_map.insert(name.to_string(), plt_entry_addr);
   380→            }
   381→        }
   382→    }
   383→
   384→    Ok(plt_map)
   385→}
   386→
   387→/// Load function sizes from a glibc shared library
   388→fn load_libc_sizes(libc_path: &PathBuf) -> Result<HashMap<String, u64>> {
   389→    let data = fs::read(libc_path)
   390→        .with_context(|| format!("Failed to read libc: {:?}", libc_path))?;
   391→
   392→    let elf = Elf::parse(&data)?;
   393→    let mut sizes = HashMap::new();
   394→
   395→    for sym in &elf.dynsyms {
   396→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   397→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   398→            sizes.insert(name.to_string(), sym.st_size);
   399→        }
   400→    }
   401→
   402→    // Also check regular symtab if available
   403→    for sym in &elf.syms {
   404→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   405→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   406→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   407→        }
   408→    }
   409→
   410→    Ok(sizes)
   411→}
   412→
   413→/// Count call references to functions using disassembly
   414→fn count_references(
   415→    args: &Args,
   416→    elf: &Elf,
   417→    binary_data: &[u8],
   418→    functions: &mut HashMap<u64, FunctionInfo>,
   419→) -> Result<()> {
   420→    let cs = Capstone::new()
   421→        .x86()
   422→        .mode(arch::x86::ArchMode::Mode64)
   423→        .syntax(arch::x86::ArchSyntax::Att)
   424→        .detail(true)
   425→        .build()
   426→        .map_err(|e| anyhow::anyhow!("Failed to create Capstone: {}", e))?;
   427→
   428→    // Find executable sections
   429→    for shdr in &elf.section_headers {
   430→        // Check if section is executable (SHF_EXECINSTR = 0x4)
   431→        if shdr.sh_flags & 0x4 == 0 {
   432→            continue;
   433→        }
   434→
   435→        let section_name = elf.shdr_strtab.get_at(shdr.sh_name).unwrap_or("");
   436→
   437→        // Skip PLT itself to avoid double-counting
   438→        if section_name == ".plt" || section_name == ".plt.got" {
   439→            continue;
   440→        }
   441→
   442→        let start = shdr.sh_offset as usize;
   443→        let end = start + shdr.sh_size as usize;
   444→
   445→        if end > binary_data.len() {
   446→            continue;
   447→        }
   448→
   449→        let section_data = &binary_data[start..end];
   450→        let section_addr = shdr.sh_addr;
   451→
   452→        let insns = cs.disasm_all(section_data, section_addr)
   453→            .map_err(|e| anyhow::anyhow!("Disassembly failed: {}", e))?;
   454→
   455→        for insn in insns.iter() {
   456→            let mnemonic = insn.mnemonic().unwrap_or("");
   457→
   458→            // Look for call and jmp instructions
   459→            if mnemonic == "call" || mnemonic == "callq" {
   460→                if let Some(target) = extract_call_target(&insn) {
   461→                    if let Some(func) = functions.get_mut(&target) {
   462→                        func.references += 1;
   463→                        if args.verbose {
   464→                            eprintln!(
   465→                                "  0x{:x}: {} -> {} (0x{:x})",
   466→                                insn.address(),
   467→                                mnemonic,
   468→                                func.name,
   469→                                target
   470→                            );
   471→                        }
   472→                    }
   473→                }
   474→            }
   475→        }
   476→    }
   477→
   478→    Ok(())
   479→}
   480→
   481→/// Extract the target address from a call instruction
   482→fn extract_call_target(insn: &capstone::Insn) -> Option<u64> {
   483→    let op_str = insn.op_str()?;
   484→
   485→    // Direct call: "0x1234" or "symbol"
   486→    // We need the absolute address
   487→
   488→    // For relative calls, capstone gives us the computed target
   489→    // Check if it's a hex address
   490→    if op_str.starts_with("0x") || op_str.starts_with("0X") {
   491→        u64::from_str_radix(&op_str[2..], 16).ok()
   492→    } else if let Ok(addr) = op_str.parse::<u64>() {
   493→        Some(addr)
   494→    } else {
   495→        // For PC-relative calls, we need to compute the target
   496→        // Format might be like "0x401234" after capstone processes it
   497→        // or it might be an indirect call like "*%rax" which we skip
   498→        if op_str.starts_with('*') {
   499→            None // indirect call
   500→        } else {
   501→            // Try parsing as hex without prefix
   502→            u64::from_str_radix(op_str.trim(), 16).ok()
   503→        }
   504→    }
   505→}
   506→
   507→fn filter_and_sort(args: &Args, functions: &mut Vec<FunctionInfo>) {
   508→    // Filter by min refs
   509→    functions.retain(|f| f.references >= args.min_refs);
   510→
   511→    // Sort
   512→    match args.sort {
   513→        SortBy::Name => functions.sort_by(|a, b| a.name.cmp(&b.name)),
   514→        SortBy::Size => functions.sort_by(|a, b| b.size.cmp(&a.size)),
   515→        SortBy::Refs => functions.sort_by(|a, b| b.references.cmp(&a.references)),
   516→    }
   517→}
   518→
   519→fn output_result(args: &Args, result: &AnalysisResult) -> Result<()> {
   520→    match args.format {
   521→        OutputFormat::Json => {
   522→            println!("{}", serde_json::to_string_pretty(result)?);
   523→        }
   524→        OutputFormat::Csv => {
   525→            println!("name,size,address,references,source");
   526→            for f in &result.functions {
   527→                println!(
   528→                    "{},{},{:#x},{},{}",
   529→                    f.name,
   530→                    f.size,
   531→                    f.address,
   532→                    f.references,
   533→                    f.source.as_deref().unwrap_or("")
   534→                );
   535→            }
   536→        }
   537→        OutputFormat::Table => {
   538→            let coverage = if result.text_section_size > 0 {
   539→                (result.total_code_size as f64 / result.text_section_size as f64) * 100.0
   540→            } else {
   541→                0.0
   542→            };
   543→
   544→            println!("Binary: {}", result.binary_path);
   545→            println!("Type: {}", if result.is_dynamic { "dynamic" } else { "static" });
   546→            println!("Functions: {}", result.total_functions);
   547→            println!(".text size: {} bytes", result.text_section_size);
   548→            println!("Total code size: {} bytes ({:.1}% coverage)", result.total_code_size, coverage);
   549→            println!();
   550→            println!("{:<40} {:>10} {:>12} {:>8}", "FUNCTION", "SIZE", "ADDRESS", "REFS");
   551→            println!("{}", "-".repeat(74));
   552→
   553→            for f in &result.functions {
   554→                println!(
   555→                    "{:<40} {:>10} {:#12x} {:>8}",
   556→                    truncate(&f.name, 40),
   557→                    f.size,
   558→                    f.address,
   559→                    f.references
   560→                );
   561→            }
   562→        }
   563→    }
   564→
   565→    Ok(())
   566→}
   567→
   568→fn truncate(s: &str, max_len: usize) -> String {
   569→    if s.len() <= max_len {
   570→        s.to_string()
   571→    } else {
   572→        format!("{}...", &s[..max_len - 3])
   573→    }
   574→}
   575→

