   174→        total1,
   175→        total2,
   176→        if total1 > 0 { format!("{:.1}x", total2 as f64 / total1 as f64) } else { "-".to_string() }
   177→    );
   178→
   179→    Ok(())
   180→}
   181→
   182→/// Extract function name -> size map from a binary
   183→fn get_function_sizes(binary: &PathBuf) -> Result<HashMap<String, u64>> {
   184→    let binary_data = fs::read(binary)
   185→        .with_context(|| format!("Failed to read binary: {:?}", binary))?;
   186→
   187→    let elf = Elf::parse(&binary_data)
   188→        .with_context(|| format!("Failed to parse ELF: {:?}", binary))?;
   189→
   190→    let mut sizes = HashMap::new();
   191→
   192→    // Check .symtab
   193→    for sym in &elf.syms {
   194→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   195→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   196→            sizes.insert(name.to_string(), sym.st_size);
   197→        }
   198→    }
   199→
   200→    // Check .dynsym
   201→    for sym in &elf.dynsyms {
   202→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   203→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   204→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   205→        }
   206→    }
   207→
   208→    Ok(sizes)
   209→}
   210→
   211→/// Get the size of the .text section
   212→fn get_text_section_size(elf: &Elf) -> u64 {
   213→    elf.section_headers
   214→        .iter()
   215→        .find(|sh| elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".text")
   216→        .map(|sh| sh.sh_size)
   217→        .unwrap_or(0)
   218→}
   219→
   220→/// Analyze a statically linked binary
   221→fn analyze_static(args: &Args, binary_path: &PathBuf, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   222→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   223→
   224→    // Collect function symbols from .symtab
   225→    for sym in &elf.syms {
   226→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   227→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   228→
   229→            // Skip if filtering and doesn't match
   230→            if let Some(ref filter) = args.filter {
   231→                if !name.contains(filter) {
   232→                    continue;
   233→                }
   234→            }
   235→
   236→            functions.insert(sym.st_value, FunctionInfo {
   237→                name: name.to_string(),
   238→                size: sym.st_size,
   239→                address: sym.st_value,
   240→                references: 0,
   241→                source: Some("local".to_string()),
   242→            });
   243→        }
   244→    }
   245→
   246→    // Also check .dynsym (release builds may strip .symtab but keep .dynsym)
   247→    for sym in &elf.dynsyms {
   248→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   249→            // Skip if we already have this address from symtab
   250→            if functions.contains_key(&sym.st_value) {
   251→                continue;
   252→            }
   253→
   254→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   255→
   256→            // Skip if filtering and doesn't match
   257→            if let Some(ref filter) = args.filter {
   258→                if !name.contains(filter) {
   259→                    continue;
   260→                }
   261→            }
   262→
   263→            functions.insert(sym.st_value, FunctionInfo {
   264→                name: name.to_string(),
   265→                size: sym.st_size,
   266→                address: sym.st_value,
   267→                references: 0,
   268→                source: Some("local".to_string()),
   269→            });
   270→        }
   271→    }
   272→
   273→    // Count references by disassembling
   274→    disasm::count_references(args.verbose, elf, binary_data, &mut functions)?;
   275→
   276→    // Convert to sorted vec
   277→    let mut func_vec: Vec<_> = functions.into_values().collect();
   278→    filter_and_sort(&args, &mut func_vec);
   279→
   280→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   281→    let text_section_size = get_text_section_size(elf);
   282→
   283→    Ok(AnalysisResult {
   284→        binary_path: binary_path.display().to_string(),
   285→        is_dynamic: false,
   286→        total_functions: func_vec.len(),
   287→        total_code_size,
   288→        text_section_size,
   289→        functions: func_vec,
   290→    })
   291→}
   292→
   293→/// Analyze a dynamically linked binary
   294→fn analyze_dynamic(args: &Args, binary_path: &PathBuf, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   295→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   296→
   297→    // For dynamic binaries, we care about:
   298→    // 1. Imported symbols (from .dynsym with UND section)
   299→    // 2. PLT entries that reference them
   300→
   301→    // Build a map of PLT entries to function names
   302→    let plt_map = build_plt_map(elf)?;
   303→
   304→    // Get sizes from libc if path provided
   305→    let libc_sizes = if let Some(ref libc_path) = args.libc_path {
   306→        load_libc_sizes(libc_path)?
   307→    } else {
   308→        HashMap::new()
   309→    };
   310→
   311→    // Collect imported libc functions
   312→    for sym in &elf.dynsyms {
   313→        if sym.st_type() == goblin::elf::sym::STT_FUNC {
   314→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   315→
   316→            if sym.st_shndx == goblin::elf::section_header::SHN_UNDEF as usize {
   317→                // Skip if filtering and doesn't match
   318→                if let Some(ref filter) = args.filter {
   319→                    if !name.contains(filter) {
   320→                        continue;
   321→                    }
   322→                }
   323→
   324→                // Find PLT address for this symbol
   325→                let plt_addr = plt_map.get(name).copied();
   326→
   327→                let size = libc_sizes.get(name).copied().unwrap_or(0);
   328→
   329→                if let Some(addr) = plt_addr {
   330→                    functions.insert(addr, FunctionInfo {
   331→                        name: name.to_string(),
   332→                        size,
   333→                        address: addr,
   334→                        references: 0,
   335→                        source: Some("glibc".to_string()),
   336→                    });
   337→                }
   338→            }
   339→        }
   340→    }
   341→
   342→    // Count references to PLT stubs
   343→    disasm::count_references(args.verbose, elf, binary_data, &mut functions)?;
   344→
   345→    let mut func_vec: Vec<_> = functions.into_values().collect();
   346→    filter_and_sort(&args, &mut func_vec);
   347→
   348→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   349→    let text_section_size = get_text_section_size(elf);
   350→
   351→    Ok(AnalysisResult {
   352→        binary_path: binary_path.display().to_string(),
   353→        is_dynamic: true,
   354→        total_functions: func_vec.len(),
   355→        total_code_size,
   356→        text_section_size,
   357→        functions: func_vec,
   358→    })
   359→}
   360→
   361→/// Build a map of function names to their PLT addresses
   362→fn build_plt_map(elf: &Elf) -> Result<HashMap<String, u64>> {
   363→    let mut plt_map = HashMap::new();
   364→
   365→    // Find .rela.plt section for PLT relocations
   366→    for reloc in &elf.pltrelocs {
   367→        let sym_idx = reloc.r_sym;
   368→        if let Some(sym) = elf.dynsyms.get(sym_idx) {
   369→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   370→
   371→            // PLT entry address: typically the relocation target + PLT base
   372→            // This is simplified; real PLT layout varies
   373→            if let Some(plt_shdr) = elf.section_headers.iter()
   374→                .find(|sh| {
   375→                    elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".plt"
   376→                })
   377→            {
   378→                // Each PLT entry is typically 16 bytes on x86_64
   379→                // First entry is resolver, real entries start at +16
   380→                let plt_entry_addr = plt_shdr.sh_addr + 16 + (plt_map.len() as u64 * 16);
   381→                plt_map.insert(name.to_string(), plt_entry_addr);
   382→            }
   383→        }
   384→    }
   385→
   386→    Ok(plt_map)
   387→}
   388→
   389→/// Load function sizes from a glibc shared library
   390→fn load_libc_sizes(libc_path: &PathBuf) -> Result<HashMap<String, u64>> {
   391→    let data = fs::read(libc_path)
   392→        .with_context(|| format!("Failed to read libc: {:?}", libc_path))?;
   393→
   394→    let elf = Elf::parse(&data)?;
   395→    let mut sizes = HashMap::new();
   396→
   397→    for sym in &elf.dynsyms {
   398→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   399→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   400→            sizes.insert(name.to_string(), sym.st_size);
   401→        }
   402→    }
   403→
   404→    // Also check regular symtab if available
   405→    for sym in &elf.syms {
   406→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   407→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   408→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   409→        }
   410→    }
   411→
   412→    Ok(sizes)
   413→}
   414→
   415→fn filter_and_sort(args: &Args, functions: &mut Vec<FunctionInfo>) {
   416→    // Filter by min refs
   417→    functions.retain(|f| f.references >= args.min_refs);
   418→
   419→    // Sort
   420→    match args.sort {
   421→        SortBy::Name => functions.sort_by(|a, b| a.name.cmp(&b.name)),
   422→        SortBy::Size => functions.sort_by(|a, b| b.size.cmp(&a.size)),
   423→        SortBy::Refs => functions.sort_by(|a, b| b.references.cmp(&a.references)),
   424→    }
   425→}
   426→
   427→fn output_result(args: &Args, result: &AnalysisResult) -> Result<()> {
   428→    match args.format {
   429→        OutputFormat::Json => {
   430→            println!("{}", serde_json::to_string_pretty(result)?);
   431→        }
   432→        OutputFormat::Csv => {
   433→            println!("name,size,address,references,source");
   434→            for f in &result.functions {
   435→                println!(
   436→                    "{},{},{:#x},{},{}",
   437→                    f.name,
   438→                    f.size,
   439→                    f.address,
   440→                    f.references,
   441→                    f.source.as_deref().unwrap_or("")
   442→                );
   443→            }
   444→        }
   445→        OutputFormat::Table => {
   446→            let coverage = if result.text_section_size > 0 {
   447→                (result.total_code_size as f64 / result.text_section_size as f64) * 100.0
   448→            } else {
   449→                0.0
   450→            };
   451→
   452→            println!("Binary: {}", result.binary_path);
   453→            println!("Type: {}", if result.is_dynamic { "dynamic" } else { "static" });
   454→            println!("Functions: {}", result.total_functions);
   455→            println!(".text size: {} bytes", result.text_section_size);
   456→            println!("Total code size: {} bytes ({:.1}% coverage)", result.total_code_size, coverage);
   457→            println!();
   458→            println!("{:<40} {:>10} {:>12} {:>8}", "FUNCTION", "SIZE", "ADDRESS", "REFS");
   459→            println!("{}", "-".repeat(74));
   460→
   461→            for f in &result.functions {
   462→                println!(
   463→                    "{:<40} {:>10} {:#12x} {:>8}",
   464→                    truncate(&f.name, 40),
   465→                    f.size,
   466→                    f.address,
   467→                    f.references
   468→                );
   469→            }
   470→        }
   471→    }
   472→
   473→    Ok(())
   474→}
   475→
   476→fn truncate(s: &str, max_len: usize) -> String {
   477→    if s.len() <= max_len {
   478→        s.to_string()
   479→    } else {
   480→        format!("{}...", &s[..max_len - 3])
   481→    }
