        .with_context(|| format!("Failed to read libc: {:?}", libc_path))?;

    let elf = Elf::parse(&data)?;
    let mut sizes = HashMap::new();

    for sym in &elf.dynsyms {
        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
